mqd_t q = mq_open("/jobs", O_CREAT | O_RDWR, 0644,
                  &(struct mq_attr){ .mq_maxmsg = 64, .mq_msgsize = 512 });
/* producer */ mq_send(q, (const char *)&job, sizeof job, 0 /*priority*/);
/* the single consumer */
char buf[512];                                  /* >= mq_msgsize */
while (mq_receive(q, buf, sizeof buf, NULL) > 0)
    handle((const struct job *)buf);
